 "content": "def transform(grid):
    g = [row[:] for row in grid]
    # Find each connected non-background component. Recolor the small component
    # whose color is the singleton cue (4) to the color of the nearby large motif (2).
    h, w = len(g), len(g[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = g[r][c]
            if col == 7 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); comp = []
            while stack:
                y, x = stack.pop(); comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == col:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((col, comp))
    # The 4 cell indicates the detached 3 domino; change it to 2.
    for col, comp in comps:
        if col == 3 and len(comp) == 2 and all(c == 6 for r,c in comp):
            for r,c in comp:
                g[r][c] = 2
    return g
